namespace Fanex.Age.UI
{
    using System.Collections;
    using System.Web;
    using System.Web.SessionState;
    using Fanex.Razorbill.Security.Configurations;
    using Alpha.SecurityCode.Configurations;
    /// <summary>
    /// Implement IHttpHandler, process request and return in JSON format.
    /// All ashx must be inherited form this handler.
    /// </summary>
    public abstract class TplHandler : TplBase, IHttpHandler, IRequiresSessionState
    {
        /// <summary>
        /// List of returning results.
        /// </summary>
        protected JsonData _Result = new JsonData(10);

        protected bool IsValidateRequest = true; 

        protected HttpContext _context;
       
        protected ISecurityCode SecurityCodeChecker
        {
            get
            {
                if (!SecurityCodeConfig.IsActive)
                {
                    return new CheckSecurityCode();
                }

                return new NewFlowSecurityCode(this.Response);
            }
        }

        public new bool IsReusable
        {
            get { return true; }
        }

        public new HttpResponse Response
        {
            get 
            {
                return _context.Response;
            }
        }

        public new HttpRequest Request
        {
            get 
            {
                return _context.Request;
            }
        }

        protected virtual string FunctionName()
        {
            return null;
        }

        public override void ProcessRequest(HttpContext context)
        {
            // ContentType always be json
            context.Response.ContentType = "text/plain";

            _context = context;
            if (context.Session == null)
            {
                SetInvalidRequest(-1);
                return;    
            }

            // Check potentially dangerous request
            try
            {
                if (IsValidateRequest)
                {
                    context.Request.ValidateInput();
                }

                // Process requested param
                _Parameters = new Hashtable();
                ProcessRequest(ref _Parameters);
            }
            catch (HttpRequestValidationException e)
            {
                SetInvalidRequest(e.ErrorCode);
                return;
            }

            context.Response.Cache.SetCacheability(HttpCacheability.NoCache);

            SetLanguage(CurrentUserSession.Language);

            // Validate request
            object obj = ValidateRequest(Parameters);

            if(obj == null)
            {
                obj = ValidateSecurityActions();
            }

            // Return error
            if (null != obj)
            {
                Result result = obj as Result;
                if (null == result)
                {
                    result = new Result(ErrorType.Unknown, obj as string);
                }

                _Result.AsResult(result as Result);
            }
            else
            {
                // check security code
                // if fail this function only return 2 error codes: required sec code or input wrong sec code
                string errMsg;
                ErrorType errCode = SecurityCodeChecker.RequiredSecurityCode(context.Request, CurrentUserSession, out errMsg);
                if (errCode == ErrorType.Success)
                {
                    // Doing data5m5
                    _View = InvokeData(Parameters);

                    RenderResult(ref _Result);
                }
                else
                {
                    Result result = new Result(errCode, errMsg);
                    if (errCode == ErrorType.RequiredSecurityCode)
                    {
                        result.ErrMsg = context.Request.RawUrl;
                    }

                    _Result.AsResult(result);
                }
            }

            Response.Write(Json.Render(_Result));

            // End
        }

        public virtual object ValidateSecurityActions()
        {
            return null;
        }

        /// <summary>
        /// Process and return a list of result.
        /// </summary>
        /// <returns></returns>
        public abstract void RenderResult(ref JsonData data);

        private void SetInvalidRequest(int errorCode)
        {
            Result error = new Result(errorCode, "Invalid parameter value.");
            _Result.AsResult(error);
            Response.Write(Json.Render(_Result));
        }
    }
}